<script setup>
import {computed} from 'vue'
import {defaultSeo} from '../../../shared/seo.js'
import MediaPicker from './MediaPicker.vue'
const model=defineModel({default:()=>({})})
const props=defineProps({title:{type:String,default:'SEO и предпросмотр ссылки'}})
const value=computed(()=>({...defaultSeo(),...model.value}))
function set(key,event){model.value={...value.value,[key]:typeof event==='string'?event:event.target.type==='checkbox'?event.target.checked:event.target.value}}
</script>
<template><details class="seo-editor"><summary>{{props.title}}</summary><div class="seo-fields"><label>SEO-заголовок (title)<input aria-label="SEO-заголовок" :value="value.title" @input="set('title',$event)" maxlength="200" placeholder="Если не заполнено — название материала и сайта"><small>{{value.title.length}} / 200</small></label><label>Метаописание (description)<textarea aria-label="Метаописание" :value="value.description" @input="set('description',$event)" rows="3" maxlength="500" placeholder="Кратко опишите содержимое страницы"></textarea><small>{{value.description.length}} / 500. Поисковая система может выбрать собственный текст сниппета.</small></label><label>Канонический адрес<input aria-label="Канонический адрес" :value="value.canonical_path" @input="set('canonical_path',$event)" maxlength="2000" placeholder="Автоматически; при необходимости /catalog"><small>Внутренний путь без параметров. Домен берётся из SEO-настроек.</small></label><p>Изображение для Open Graph</p><MediaPicker @select="set('image_url',$event)"/><div v-if="value.image_url"><img :src="value.image_url" alt="Изображение ссылки"><button type="button" class="row-btn" @click="set('image_url','')">Убрать изображение</button></div><label class="seo-check"><input type="checkbox" :checked="value.noindex" @change="set('noindex',$event)"> Не индексировать страницу (noindex)</label><label class="seo-check"><input type="checkbox" :checked="value.nofollow" @change="set('nofollow',$event)"> Не переходить по ссылкам (nofollow)</label><p>Open Graph, Twitter Card и микроразметка формируются автоматически. SEO-поля сохраняются вместе с материалом.</p></div></details></template>
<style scoped>
.seo-editor{border:1px solid #d6e2da;padding:16px;border-radius:8px;min-width:0}.seo-editor summary{cursor:pointer;font-weight:700}.seo-fields{display:grid;gap:16px;margin-top:16px;min-width:0}.seo-fields label{display:grid;gap:8px;font-size:13px}.seo-fields input:not([type=checkbox]),.seo-fields textarea{width:100%;min-width:0;padding:10px;border:1px solid #cadbd0;border-radius:6px;font:inherit}.seo-check{display:flex!important;align-items:center}.seo-fields img{max-width:180px;max-height:100px;object-fit:contain}.seo-fields small,.seo-fields p{font-size:12px;line-height:1.6;color:#5c7064;margin:0;overflow-wrap:anywhere}
</style>
